INSERT INTO species (park_id, common_name, scientific_name, kingdom, family, primary_habitat, description, description_source, identification_tips, seasonality, image_url, image_attribution, latitude, longitude, rarity_score, rarity_basis, rarity_local, rarity_local_basis, is_featured, is_visible, hidden_reason, source, taxon_phylum, taxon_class, taxon_order, taxon_family, taxon_genus, iucn_global, iucn_spain, spain_status, regional_status, regional_ccaa, review_note, eidos_taxonid, gbif_species_key, gbif_occurrences, zepa_site_code, is_migratory, site_presence)
SELECT pk.id, s.common_name, s.scientific_name, s.kingdom, s.family, s.primary_habitat, s.description, s.description_source, s.identification_tips, s.seasonality, s.image_url, s.image_attribution, s.latitude, s.longitude, s.rarity_score, s.rarity_basis, s.rarity_local, s.rarity_local_basis, s.is_featured, s.is_visible, s.hidden_reason, s.source, s.taxon_phylum, s.taxon_class, s.taxon_order, s.taxon_family, s.taxon_genus, s.iucn_global, s.iucn_spain, s.spain_status, s.regional_status, s.regional_ccaa, s.review_note, s.eidos_taxonid, s.gbif_species_key, s.gbif_occurrences, s.zepa_site_code, s.is_migratory, s.site_presence
FROM parks pk JOIN (
    SELECT 'Jabalí' common_name, 'Sus scrofa' scientific_name, 'fauna' kingdom, 'Mamífero ungulado' family, 'Bosque, matorral denso y cultivos; necesita cobertura y puntos de agua' primary_habitat, 'Ungulado robusto y adaptable, con el cuerpo cubierto de cerdas ásperas y una cabeza en cuña rematada por un hocico potente con el que remueve el suelo. Los rayones —las crías— nacen con líneas claras a lo largo del lomo. Es omnívoro y ha ampliado mucho su área en las últimas décadas.' description, NULL description_source, 'Hozaduras: zonas de suelo removido como si lo hubieran arado; Huellas hendidas grandes con las pezuñas laterales marcadas; Barros y árboles con el tronco embarrado a media altura' identification_tips, 'Todo el año (actividad sobre todo nocturna)' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Eberswalde_Zoo_12-2017_img2.jpg?width=1280' image_url, 'A.Savin (FAL) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}' rarity_basis, 1 rarity_local, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}' rarity_local_basis, 0 is_featured, 1 is_visible, NULL hidden_reason, 'GBIF: 45 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas' source, 'Chordata' taxon_phylum, 'Mammalia' taxon_class, 'Artiodactyla' taxon_order, 'Suidae' taxon_family, 'Sus' taxon_genus, 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)' iucn_global, 'LC — Preocupación menor (Lista Roja española, 2007)' iucn_spain, 'No catalogada (especie cinegética común)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)' regional_status, 'Región de Murcia' regional_ccaa, NULL review_note, 12178 eidos_taxonid, 7705930 gbif_species_key, 45 gbif_occurrences, NULL zepa_site_code, NULL is_migratory, NULL site_presence
    UNION ALL
    SELECT 'Zorro', 'Vulpes vulpes', 'fauna', 'Mamífero carnívoro', 'Prácticamente cualquier ambiente: bosque, matorral, cultivos y periferias urbanas', 'El carnívoro silvestre más adaptable y extendido: vive desde la alta montaña hasta el borde de las ciudades. Es omnívoro y oportunista, lo que explica su éxito. Se reconoce por la cola larga y espesa —la «hopa»— rematada casi siempre en blanco.', NULL, 'Cola muy espesa con la punta blanca; Huella alargada con las cuatro almohadillas alineadas; Excrementos retorcidos y con pelos, sobre piedras y caminos', 'Todo el año (actividad sobre todo nocturna)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vulpes_vulpes_2.jpg?width=1280', 'Juan Lacruz (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 40 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Mammalia', 'Carnivora', 'Canidae', 'Vulpes', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2021)', 'LC — Preocupación menor (Lista Roja española, 2007)', 'No catalogada (especie cinegética común)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 12419, 5219243, 40, NULL, NULL, NULL
    UNION ALL
    SELECT 'Enebro de la miera', 'Juniperus oxycedrus', 'flora', 'Conífera', 'Matorral, pinares aclarados y laderas pedregosas', 'Enebro de hojas aciculares y punzantes dispuestas de tres en tres, con dos bandas blancas en la cara superior que lo separan a simple vista de la sabina. Sus gálbulos son rojizos al madurar. De su madera se destilaba el aceite de miera.', NULL, 'Hojas punzantes en grupos de tres, no en escama; Dos rayas blancas en la cara superior de cada hoja; Gálbulos rojizos y brillantes al madurar', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Juniperus_oxycedrus_g1.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 1, 1, NULL, 'GBIF: 8 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha, que la cita como «Juniperus oxycedrus subsp. oxycedrus», con la categoría «De Interés Especial (Catálogo Regional de Flora Silvestre Protegida)»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Pinopsida', 'Pinales', 'Cupressaceae', 'Juniperus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2013)', NULL, 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO XII. Especies a las que se refiere la disposición adicional tercera (otras especies forestales importantes para la selvicultura en España) (Real Decreto 289/2003, de 7 de marzo, sobre la comercialización de los materiales forestal…)', 'En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 5505, 2684451, 8, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cabra montés', 'Capra pyrenaica', 'fauna', 'Mamífero ungulado', 'Roquedos, canchales y laderas escarpadas con matorral', 'Bóvido de montaña perfectamente adaptado a la roca: pezuñas con borde duro y almohadilla blanda que agarra en pendientes imposibles. Los machos lucen cuernos grandes, curvados hacia atrás y con abultamientos; las hembras los tienen cortos y rectos.', NULL, 'Machos con cuernos grandes curvados hacia atrás; Se mueve por cortados donde nada más puede subir; Excrementos en montoncitos de bolitas cilíndricas', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Capra_pyrenaica_in_Sierra_de_Guadarrama.jpg?width=1280', 'Thomas Holbach (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Mammalia', 'Artiodactyla', 'Bovidae', 'Capra', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2021)', 'NT — Casi amenazada (Lista Roja española, 2007)', 'Anexo VI (Ley 42/2007, de 13 de diciembre)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 12055, 2441054, 4, NULL, NULL, NULL
    UNION ALL
    SELECT 'Jara blanca', 'Cistus albidus', 'flora', 'Mata', 'Matorral y laderas soleadas sobre suelos calizos secos', 'Jara de hojas blanquecinas, aterciopeladas al tacto y sin peciolo, con flores grandes de color rosa malva y pétalos arrugados como papel de seda que duran solo unas horas. Es una de las plantas que da color al matorral en primavera.', NULL, 'Hojas blanquecinas y aterciopeladas, sentadas en la rama; Flores rosa malva grandes, de pétalos arrugados; Cada flor dura apenas una mañana', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cistus_albidus_flowers.jpg?width=1280', 'Júlio Reis (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Cistus', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 3609, 7331435, 4, NULL, NULL, NULL
    UNION ALL
    SELECT 'Coscoja', 'Quercus coccifera', 'flora', 'Arbusto', 'Matorral esclerófilo y sabinar', 'Arbusto esclerófilo de hoja perenne y espinosa, integrante del matorral mediterráneo denso y de las orlas del sabinar.', NULL, 'Hojas coriáceas con margen espinoso; Bellota con cúpula de escamas punzantes; Porte arbustivo denso', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Quercus_coccifera_1.JPG?width=1280', 'User:Xemenendura (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Fagales', 'Fagaceae', 'Quercus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', NULL, 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo) · ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo) · ANEXO XII. Especies a las que se refiere la disposición adicional tercera (otras especies forestales importantes para la selvicultura en España) (Real Decreto 289/2003, de 7 de marzo)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 7478, 2879175, 4, NULL, NULL, NULL
    UNION ALL
    SELECT 'Pino carrasco', 'Pinus halepensis', 'flora', 'Conífera', 'Laderas secas y soleadas sobre calizas y margas, en clima mediterráneo cálido', 'Pino de copa clara e irregular y follaje de un verde pálido, el más resistente a la sequía y a los suelos pobres de los pinos ibéricos. Sus piñas, alargadas y asimétricas, quedan colgadas años en la rama y liberan las semillas tras los incendios, lo que le permite recolonizar rápido.', NULL, 'Copa irregular y poco densa, de verde claro; Piñas asimétricas y persistentes, apuntando hacia atrás; Corteza clara y agrietada, rojiza en las ramas jóvenes', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pino_secolare_-_Castelleone_di_Suasa.JPG?width=1280', 'Accurimbono (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Pinopsida', 'Pinales', 'Pinaceae', 'Pinus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2013)', NULL, 'No catalogada (especie forestal común)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 7118, 5285604, 3, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lentisco', 'Pistacia lentiscus', 'flora', 'Arbusto', 'Matorral mediterráneo litoral', 'Arbusto perennifolio de hojas compuestas sin foliolo terminal y con el raquis alado, un detalle que lo separa de la cornicabra. Al frotarlo huele intensamente a resina. Sus frutos, en racimo, pasan de rojo a negro y son alimento clave para aves en otoño.', NULL, 'Hoja compuesta con número par de foliolos, sin uno terminal; Raquis de la hoja con dos alas laterales; Olor fuerte a resina al frotar las hojas', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pistacia_lentiscus.jpg?width=1280', 'Lumbar~commonswiki (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Sapindales', 'Anacardiaceae', 'Pistacia', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', NULL, 'No catalogada (especie común mediterránea)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 7129, 3190583, 3, NULL, NULL, NULL
    UNION ALL
    SELECT 'Romero', 'Rosmarinus officinalis', 'flora', 'Mata aromática', 'Matorral seco y soleado sobre suelos calizos y pedregosos', 'Arbusto aromático de hojas estrechas como agujas, verde oscuro por el haz y blanquecinas por el envés, con los bordes enrollados hacia abajo. Florece casi todo el año en azul pálido, y en pleno invierno es una de las pocas fuentes de néctar del matorral.', NULL, 'Hojas como agujas, blancas por debajo; Olor inconfundible al frotar entre los dedos; Flores azul claro repartidas por las ramas casi todo el año', 'Todo el año, con máximo de floración en invierno y primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rosemary_in_bloom.JPG?width=1280', 'Margalob (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Rosmarinus', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 7647, 10902460, 3, NULL, NULL, NULL
    UNION ALL
    SELECT 'Romerina', 'Cistus clusii', 'flora', 'Mata', 'Tomillares y matorral seco sobre calizas y margas', 'Jara pequeña de hojas muy estrechas y enrolladas por los bordes, verdes arriba y blancas por debajo, que a distancia recuerdan al romero. Se distingue enseguida al florecer: da grupos de flores blancas de cinco pétalos, mucho mayores que las del romero.', NULL, 'Hojas estrechas enrolladas, blancas por el envés; Flores blancas de cinco pétalos, varias juntas; Sin el olor a romero, aunque se le parezca de lejos', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cistus_clusii_(habitus).jpg?width=1280', 'Hans Hillewaert (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Cistus', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 3610, 7331346, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'Carrasca', 'Quercus rotundifolia', 'flora', 'Árbol', 'Bosques y matorrales mediterráneos continentales, sobre suelos secos y pobres', 'La encina de interior, más adaptada al frío y a la sequía continental, con hojas más redondeadas y bellotas dulces. A menudo crece en mata por el efecto del ramoneo y las cortas repetidas. Muchos autores la consideran una subespecie de la encina.', NULL, 'Hojas más redondeadas y pequeñas que las de la encina litoral; Bellotas de sabor dulce, no amargas; Frecuente en porte de mata, con varios pies', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Carrasca_de_la_Raboseras.JPG?width=1280', 'Picamaderos (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha, con la categoría «De Interés Especial (Catálogo Regional de Flora Silvestre Protegida)»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Fagales', 'Fagaceae', 'Quercus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', NULL, 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se c