    SELECT 'Lagartija colilarga', 'Psammodromus algirus', 'fauna', 'Reptil', 'Matorral litoral y laderas secas', 'Lagartija esbelta de escamas grandes, quilladas y brillantes, con dos líneas claras muy marcadas a cada lado del dorso. La cola puede medir el doble que el cuerpo. Los machos lucen en primavera manchas azules en el hombro y las mejillas anaranjadas.', NULL, 'Dos líneas claras nítidas a lo largo de cada costado; Escamas grandes y quilladas, de aspecto brillante; Cola larguísima, hasta el doble que el cuerpo', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Psammodromus_algirus_-_01.jpg?width=1280', 'Carlos Delgado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Squamata', 'Lacertidae', 'Psammodromus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2009)', 'LC — Preocupación menor (Lista Roja española, 2002)', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 10670, 2469763, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Aladierno', 'Rhamnus alaternus', 'flora', 'Arbusto', 'Matorral alto, encinares y barrancos sobre suelos pedregosos', 'Arbusto perennifolio de hojas alternas, coriáceas y de borde finamente dentado, sin espinas. Sus frutos maduran de rojo a negro y son muy buscados por los pájaros. Se distingue del espino negro por carecer de espinas y tener hojas mayores.', NULL, 'Sin espinas, a diferencia de otros ramnos; Hojas alternas, coriáceas y algo dentadas; Frutos que pasan de rojo a negro al madurar', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rhamnus_alaternus1627.JPG?width=1280', 'tato grasso (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha, con la categoría «De Interés Especial (Catálogo Regional de Flora Silvestre Protegida)»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Rhamnaceae', 'Rhamnus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', NULL, 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 7684, 6371424, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Sedo de hojas gruesas', 'Sedum dasyphyllum', 'flora', 'Planta suculenta', 'Prados calcáreos del Alysso-Sedion albi', 'Crasulácea diminuta de hojas gruesas, casi esféricas y de un gris azulado, dispuestas de dos en dos y cubiertas de pelillos glandulosos que la hacen pegajosa. Forma almohadillas en grietas y muros y da flores blancas con venas rosadas.', NULL, 'Hojas casi esféricas, opuestas y de gris azulado; Tacto pegajoso por los pelillos glandulosos; Flores blancas con finas venas rosadas', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sedum_dasyphyllum_(1)_6.jpg?width=1280', 'Ghislain118 http://www.fleurs-des-montagnes.net (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Saxifragales', 'Crassulaceae', 'Sedum', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 8203, 7172720, 1, NULL, NULL, NULL
