    SELECT 'Acentor alpino', 'Prunella collaris', 'fauna', 'Ave', 'Roquedos y pedreras de alta montaña; en invierno baja a cortados', 'Pájaro robusto de montaña, pardo y discreto salvo por dos detalles: los flancos con listas castañas y una garganta blanca finamente moteada de negro. Camina entre las rocas buscando insectos y semillas, y en invierno desciende a cortados y construcciones.', NULL, 'Flancos con anchas listas castañas; Garganta blanca con motas negras, como un babero; Base del pico amarilla', 'Otoño e invierno en cotas bajas', 'https://commons.wikimedia.org/wiki/Special:FilePath/Alpine_accentor_saganta.jpg?width=1280', 'Paco Gómez from Castellón, Spain (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha, con la categoría «Migradora de llegada regular (Directiva Aves)»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Prunellidae', 'Prunella', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 11054, 5231770, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Chochín', 'Troglodytes troglodytes', 'fauna', 'Ave', NULL, 'El chochín común es un pajarillo de pequeño tamaño, aspecto compacto, cabeza voluminosa y cola corta, que se caracteriza por poseer un plumaje pardo-rojizo —algo más claro en las partes inferiores— finamente vermiculado de tonos más oscuros. Sobre el ojo presenta una marcada ceja de color crema. El pico es fino y algo curvado, con distinta longitud según la subespecie. Las diferencias entre edades y sexos son muy sutiles y resultan difíciles de reconocer en el campo. De carácter inquieto, el chochín —una de las especies más pequeñas de nuestra avifauna— cuando se excita suele sacudir y levantar su cola formando un ángulo de 90 grados, antes de desaparecer entre la densa vegetación.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Carri%C3%A7a%2C_carricinha%2C_carruira%2C_no_seu_canto_possante_e_melodioso%2C_Winter_Wren%2C_with_a_melodious_and_powerful_singing_(53737498699)_(cropped).jpg?width=1280', 'Luiz Lapa from Oeiras, Portugal (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha, que la cita como «Troglodites troglodites» (errata de la tabla: se lee «Troglodites troglodites» por Troglodytes troglodytes); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Troglodytidae', 'Troglodytes', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 12340, 5231438, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lagartija colirroja', 'Acanthodactylus erythrurus', 'fauna', 'Reptil', 'Matorral litoral y laderas secas', 'Lagartija de suelos arenosos, de cuerpo aplanado y dedos con escamas laterales en forma de peine que le sirven de raqueta sobre la arena suelta. Los jóvenes tienen la cola y las patas traseras de un rojo intenso que se apaga en los adultos.', NULL, 'Dedos con flecos de escamas a los lados, como peines; Jóvenes con cola y patas traseras rojo intenso; Cuerpo aplanado, con rayas y ocelos claros en el dorso', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Benny_Trapp_Acanthodactylus_erythrurus.jpg?width=1280', 'Benny Trapp (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-09-13); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Squamata', 'Lacertidae', 'Acanthodactylus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2009)', 'LC — Preocupación menor (Lista Roja española, 2002)', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 11220, 5226733, 0, NULL, NULL, NULL
    UNION ALL
    SELECT 'Sapo partero común', 'Alytes obstetricans', 'fauna', 'Anfibio', NULL, 'Sapo de tamaño pequeño (menor de 5 cm). Aspecto rechoncho, cabeza grande y hocico redondeado, ojos prominentes, pupila vertical e iris dorado con vetas negras. Tímpano visible y más pequeño que el ojo. Pliegue gular patente. Glándulas parotídeas poco aparentes. Piel granulosa con verrugas pequeñas, frecuentemente agrupadas en los costados en dos hileras dorsolaterales. Miembros cortos y fuertes, los anteriores con 3 tubérculos metacarpianos, y los posteriores con membrana interdigital muy reducida y con un tubérculo metatarsiano pequeño. Coloración dorsal de gris a parda con pequeñas manchas verdes, rojizas y negras poco marcadas. Zona ventral clara.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Febrero a octubre', 'https://commons.wikimedia.org/wiki/Special:FilePath/AlytesObstet.jpg?width=1280', 'Christian Fischer (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-09-13); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha, que la cita como «Alytes obstreticans» (errata de la tabla: se lee «obstreticans» por obstetricans); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Amphibia', 'Anura', 'Alytidae', 'Alytes', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2022)', 'NT — Casi amenazada (Lista Roja española, 2002)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 11878, 2426612, 0, NULL, NULL, NULL
    UNION ALL
    SELECT 'Gayuba', 'Arctostaphylos uva-ursi', 'flora', 'Mata', 'Pinares aclarados, crestas y laderas pedregosas de montaña', 'Mata rastrera de hojas pequeñas, coriáceas y brillantes que forma alfombras densas sobre el suelo del pinar. Sus flores son urnas blanco rosadas colgantes y sus frutos, bayas rojas y harinosas. Ayuda a fijar el suelo en laderas pedregosas.', NULL, 'Porte rastrero formando alfombras continuas; Hojas pequeñas, duras y muy brillantes; Flores en urna colgante y frutos rojos harinosos', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gayuba.jpg?width=1280', 'No machine-readable author provided. Carlosblh assumed (based on co… (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-09-13); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha, que la cita como «Arctostaphylos uva-ursi subsp. crassifolia», con la categoría «De Interés Especial (Catálogo Regional de Flora Silvestre Protegida)»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Ericales', 'Ericaceae', 'Arctostaphylos', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 2292, 2882580, 0, NULL, NULL, NULL
    UNION ALL
    SELECT 'Falguera', 'Asplenium trichomanes', 'flora', 'Helecho', 'Vive en grietas de roquedos calizos o silíceos, hasta 2000 m', 'Helecho de rizoma pequeño, completamente cubierto de escamitas color castaño; frondes hasta de 25 cm, con pecíolo corto y raquis oscuros y brillantes, con pinnas en disposición alterna y perpendicular al raquis, enteras, ovadas, suavemente dentadas y algo onduladas, con cuatro a diez soros alargados que nacen en las nervios laterales. Esporas hasta de 45 micras, color castaño.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Trichomanes-grazalema.jpg?width=1280', 'Juan Bibiloni (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-09-13); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Polypodiopsida', 'Polypodiales', 'Aspleniaceae', 'Asplenium', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 2555, 8108066, 0, NULL, NULL, NULL
