-- ------------------------------------------------------------------------------------------------
-- 4. Vínculos especie↔hábitat (24). `evidence` = lo que declara el `source` de cada ficha; ver cabecera.
-- ------------------------------------------------------------------------------------------------
INSERT INTO species_habitats (species_id, habitat_id, evidence)
SELECT sp.id, hb.id, v.evidence
FROM parks pk
JOIN (
    SELECT 'Sus scrofa' scientific_name, 'matorrales-termomediterraneos-y-5330' habitat_slug, 'observada_gbif' evidence
    UNION ALL
    SELECT 'Vulpes vulpes', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Juniperus oxycedrus', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Capra pyrenaica', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Cistus albidus', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Quercus coccifera', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Pinus halepensis', 'matorrales-termomediterraneos-y-5330', 'caracteristica'
    UNION ALL
    SELECT 'Pistacia lentiscus', 'pendientes-rocosas-calcicolas-8210', 'observada_gbif'
    UNION ALL
    SELECT 'Pistacia lentiscus', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Rosmarinus officinalis', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Cistus clusii', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Quercus rotundifolia', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Rhamnus oleoides', 'matorrales-termomediterraneos-y-5330', 'caracteristica'
    UNION ALL
    SELECT 'Sarcocapnos enneaphylla', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Anthyllis cytisoides', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Anthyllis lagascana', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Arbutus unedo', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Fritillaria lusitanica', 'pendientes-rocosas-calcicolas-8210', 'observada_gbif'
    UNION ALL
    SELECT 'Psammodromus algirus', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Rhamnus alaternus', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Sedum dasyphyllum', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Teucrium franchetianum', 'pendientes-rocosas-calcicolas-8210', 'observada_gbif'
    UNION ALL
    SELECT 'Teucrium franchetianum', 'matorrales-termomediterraneos-y-5330', 'caracteristica'
    UNION ALL
    SELECT 'Thymelaea tartonraira', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
) v
JOIN species sp ON sp.park_id = pk.id AND sp.scientific_name = v.scientific_name
JOIN habitats hb ON hb.park_id = pk.id AND hb.slug = v.habitat_slug
WHERE pk.slug = 'monte-arabi'
ON DUPLICATE KEY UPDATE evidence = VALUES(evidence);

-- ------------------------------------------------------------------------------------------------
-- 5. Comprobación posterior. Debe devolver exactamente los recuentos de la cabecera.
-- ------------------------------------------------------------------------------------------------
SELECT
    (SELECT COUNT(*) FROM parks WHERE slug = 'monte-arabi') AS espacio,
    (SELECT COUNT(*) FROM habitats h JOIN parks p ON p.id = h.park_id WHERE p.slug = 'monte-arabi') AS habitats,
    (SELECT COUNT(*) FROM species s JOIN parks p ON p.id = s.park_id WHERE p.slug = 'monte-arabi') AS especies,
    (SELECT COUNT(*) FROM species_habitats sh JOIN species s ON s.id = sh.species_id JOIN parks p ON p.id = s.park_id WHERE p.slug = 'monte-arabi') AS vinculos;
